import React from 'react'
import { Link } from 'react-router-dom'
export default function Navbar() {
  return (
    <div >
    <nav className='navbar'>
         <h1>EthioNexa</h1> 
        <div className='links'>
             <Link to ="/">Home</Link>
        <Link className='but' to="/Login" style={{ 
          color: 'white', 
          backgroundColor: 'brown',
        
          borderRadius: '8px' 
        }}>Login</Link>
        </div>
    </nav>
    </div>
  )
}
